spec.expr:
sum by (phase, target_rps, operation_type) (
  rate(k6_http_reqs_total{
    phase="measure",
  }[2s])
)

avg by (phase, target_rps, operation_type) (
  avg_over_time(
    k6_http_req_duration_p95{
      phase="measure",
    }[2s]
  ) * 1000
)

sum by (http_method, http_route, http_status_code) (
  rate(traces_spanmetrics_calls_total{
    job="taxi-manager-django-wsgi",
    service_name="taxi-manager-django-wsgi",
    span_kind="SPAN_KIND_SERVER",
    http_route!="prometheus/metrics"
  }[30s])
)

1000 *
histogram_quantile(
  0.95,
  sum by (le) (
    rate(traces_spanmetrics_duration_seconds_bucket{
      job="taxi-manager-django-wsgi",
      service_name="taxi-manager-django-wsgi",
      span_kind="SPAN_KIND_SERVER",
      http_route="api/v1/vehicles/<int:vehicle_id>/trip-points/"
    }[30s])
  )
)

avg by (phase, target_rps, operation_type) (
  avg_over_time(
    k6_http_req_waiting_p95{
      phase="measure",
    }[2s]
  ) * 1000
)

sum by (phase, target_rps, operation_type,status) (
  rate(k6_http_reqs_total{
    phase="measure",
    expected_response="true"
  }[2100ms])
)

sum by (phase, target_rps, operation_type, status) (
  rate(k6_http_reqs_total{
    phase="measure",
    expected_response="false"
  }[2s])
)

100 *
sum by (phase, target_rps, operation_type) (
  rate(k6_http_reqs_total{
    phase="measure",
    expected_response!="true"
  }[2s])
)
/
sum by (phase, target_rps, operation_type) (
  rate(k6_http_reqs_total{
    phase="measure"
  }[2s])
)
